// 2025-1-21 
// 五网格法画彭罗斯镶嵌
// Penrose tiling pentagrid method
//
// golf version：
// https://www.shadertoy.com/view/MXcfRX
// 
// from:
// https://www.desmos.com/calculator/g4wcmzmn3s
// https://new.math.uiuc.edu/oldnew/quasicrystals/papers/debruijnPenrose.pdf
// http://www.geom.uiuc.edu/apps/quasitiler/about.html



// Looking at the documentation and examples feels like reading an ancient text. I spent a long time but couldn't understand it.
//
// The real algorithm is quite simple:
// Find an intersection point on the grid,
// project it onto the vectors, round it, and accumulate to find the vertex.
// By taking one more step along the perpendicular directions of the two intersecting lines, you can find two more points.
// The fourth vertex can even be directly derived by adding or subtracting the first three vertices.
//
// For Shadertoy, finding the intersection point based on the coordinates is easy.
// The difficulty lies in the fact that the "determined intersection point" and the rhombus are not in the same place, and the pixel-to-rhombus straight-line distance is much greater than 0, making it impossible to use a distance field for drawing.
// Fortunately, after some experiments, I found that shrinking the rhombus by 2.5 times brings it close to the intersection point. At least for small-scale drawing, it works well enough. This relationship is truly fascinating.


#define CorrectLighting 1

#define TAU 6.28318531
float w[5];
vec2 unit5[5];float C[5],S[5];

void init()
{
        w = float[]( .35353, .45677, .54367, .67777, .77477 );  // 要求： w[0]+w[1]+w[2]+w[3]+w[4]==0
        // The purpose of w[] is to move five sets of parallel lines to change the diamond distribution. The requirement is that after moving the parallel lines, no intersection point in the network should have more than two lines passing through it. This is because the two lines at each intersection will determine the two sets of parallel edges of the diamond. If there are more lines, it will cause an error (there are only a few fixed directions, and one mistake will cause the entire row to be incorrect).
        // w[] 的目的是移动五组平行线，以改变菱形分布。要求是，它们移动平行线后，网络之中任意两条线交点位置不会有更多的直线经过。因为每个交点上的两条直线会决定菱形的两组平行边，多了就会出错（方向只有固定几个，一个错则一行都错）。

        vec2 a = vec2(cos(iTime),sin(iTime*.2));

        for(int  i=0;i<5;i++)
        {
                unit5[i] = vec2(cos(TAU * float(i) / 5.), sin(TAU * float(i) / 5.)) ;
                //w[i] = dot(unit5[i],a)*-.49+.5;
        }
        w[3]=a.x*.4+.512121211;
        //w[4]=0.-w[0]-w[1]-w[2]-w[3];


}

float line(vec2 a, vec2 b, vec2 p){
        b-=a; p-=a;
        return length(p - b * clamp(dot(p,b)/dot(b,b), 0., 1.));
}



vec2 path(vec2 p, int who){ // why  -dot()/10e10 precision error ???
        vec2 sum = vec2(0);
        float c;
        for(int i=0;i<5;i++){
                c = ceil(dot(unit5[i], p) + w[i] - .001);//dot(unit5[i], unit5[i])/1e3);
                //c = round(.5 + dot(unit5[i], p) + w[i] - dot(unit5[i], unit5[i])/1e3);   

                c += float(i == who);
                sum += unit5[i] * c;
        }
        return sum / 2.5;
}



