}*/


vec2 intersectionPoint(ivec2 ab, vec2 mn){
        vec2 p = (mn.x - w[ab.x]) * unit5[ab.x],
             q = (mn.y - w[ab.y]) * unit5[ab.y];
        vec2 np = unit5[ab.x].yx * vec2(-1,1),
             nq = unit5[ab.y].yx * vec2(-1,1);
        float e =  p.x *  np.y -  np.x *  p.y,
              f =  q.x *  nq.y -  nq.x *  q.y,
              g =  nq.x *  np.y -  nq.y *  np.x;
        vec2 c = ( nq * e -  np * f) / g;
        return c;
}



float cross2(vec2 a, vec2 b){
        return a.x*b.y-a.y*b.x;
}

bool inDiamond(vec2 a, vec2 b, vec2 c, vec2 d, vec2 p){// optional
        float f1 = cross2(p-a, b-a),
              f2 = cross2(p-b, c-b),
              f3 = cross2(p-c, d-c),
              f4 = cross2(p-d, a-d);
              //return true;
        return !((f1*f2<0.)||(f1*f3<0.)||(f1*f4<0.));
}

vec4 color(ivec2 id)// 10种 hash
{// https://www.shadertoy.com/view/4djSRW
    vec4 p4;// = fract(vec4(id.xyxy) * vec4(.1031, .1030, .0973, .1099)+ floor(iTime)*.1234);// 0. 7. 109 140 149 155

    p4 = fract(vec4(id.xyxy) * vec4(.1031, .1030, .0973, .1099)+ 140.*.1234);


    p4 += dot(p4, p4.wzxy+33.33);
    return fract((p4.xxyz+p4.yzzw)*p4.zywx);
}


float minLine(float dist,vec2 cent, vec2 a,vec2 b,vec2 u,inout vec2 nrm){
        float d = line(a,b,u);
        if(d<dist)
        {
                nrm = (a-b).yx*vec2(-1,1);
                if(dot(nrm,a-cent)<0.)nrm=-nrm;
                dist=d;
        }
        return dist;
}

void mainImage(out vec4 O, vec2 U)
{
        init();
        vec2 R = iResolution.xy,
             u = 2.5 * (U+U +.1- R) / R.y + 30.*cos(iTime*.03+vec2(0,11));


        O =vec4(.7);
        float dist = 1e8;
        vec2 nrm;

        //
        //for(E11.y=-W;E11.y<=W;E11.y++)
        //for(E11.x=-W;E11.x<=W;E11.x++)
        //for(int uv = 0; uv < D*D; uv++)// 3*3 还不保险，有较b少漏过， 5*5 ok        
        //nearbyTest = (ivec2(uv % D, uv / D )+W) % D - W; // [-1 to 1][ -1 to 1] 加速用 0 在前

        // Easy to spot the error:
        // nearbyTest: [0 to 0][0 to 0]   (W=0)
        //
        // Most of it is correct (currently used):
        // nearbyTest: [-1 to 1][-1 to 1] (W=1)
        //
        // Possible one in ten thousand error
        // nearbyTest: [-2 to 2][-2 to 2] (W=2)
        //
        // I personally believe there will be no error
        // nearbyTest: [-3 to 3][-3 to 3] (W=3)
        //
        // Except for calculation precision issues

        int W = 1,  
            D=2*W+1;
        for(int uv = 0 ; uv < D*D; uv++)// 3*3 还不保险，有较b少漏过， 5*5 ok
        { // 九宫格
                //ivec2 nearbyTest = (ivec2(uv % 3, uv / 3 )+1) % 3 - 1; // [-1 to 1][ -1 to 1] 加速用 0 在前
                ivec2 nearbyTest = (ivec2(uv % D, uv / D )+W) % D - W; // [-1 to 1][ -1 to 1] 加速用 0 在前


                // 扫描
                //dist = 1e8;
                for(int i=0; i<10; i++)
                {
                        ivec2 directionIDs = ivec2(i*3, i*3+1 + (i/5)*2) % 5;
                        vec2 grid;
                        grid.x = dot(u, unit5[directionIDs.x]) + w[directionIDs.x];
                        grid.y = dot(u, unit5[directionIDs.y]) + w[directionIDs.y];
                        grid = round(grid); 
                        vec2 Xp = intersectionPoint(directionIDs, grid + vec2(nearbyTest));
                        //O += length(u-mn);return;
                        vec2 a = path(Xp, directionIDs.x),
                             b = path(Xp, 6666),
                             c = path(Xp, directionIDs.y),
                             d = a + c - b;
                        if(inDiamond(a, b, c, d, u))// optional
                        {
                                vec2 cent = (a+c)*.5, f=u, s=vec2(1);
                           #if CorrectLighting == 2
                                // Incorrect lighting, but with the illusion of being pressed and released.
                                if(dot(f-cent,a-c)<0.)f = reflect(f-cent, normalize(a-c))+cent,s.x=-s.x;
                                if(dot(f-cent,b-d)<0.)f = reflect(f-cent, normalize(b-d))+cent,s.y=-s.y;
                                dist = min(dist, line(a,b,f));
                                if(dist < 9.){
                                        O = .1-vec4( smoothstep( 10./ R.y, 0., dist) );
                                        if(O.x>.65)
                                             O = O*.8+.5*color(directionIDs);                                        
                                        vec3 norm = normalize(vec3(smoothstep(.1, 0.,dist)* normalize(a-b).yx*vec2(-1,1)*s,1));
                                        vec3 sun = normalize(vec3(-2,-3,4));                                        
                                        O += max(0., dot(norm,sun))* color(directionIDs) ;                                                                                
                                        return ;
                                }
                           #elif CorrectLighting ==1                           
                                // right version
                                dist = minLine(dist,cent, a,b,u,nrm);
                                dist = minLine(dist,cent, c,b,u,nrm);
                                dist = minLine(dist,cent, c,d,u,nrm);
                                dist = minLine(dist,cent, d,a,u,nrm);                                                                                                
                                if(dist < 9.){
                                        //if(O.x>.65)
                                             O = .0-vec4( smoothstep(.02, 0., dist) ) ;                                        
                                        vec3 norm = normalize(vec3(smoothstep(.1, 0.,dist)* nrm,1));                                       
                                        vec3 sun = normalize(vec3(-2,3,3));    
                                        float dt = max(0., dot(norm,sun));
                                        O += 1.5*dt* color(directionIDs) + 3.*pow(dt+.1,30.) ;                                        
                                        return ;
                                }
                           #else
                                dist = min(dist, line(a,b,u));
                                dist = min(dist, line(c,b,u));
                                dist = min(dist, line(c,d,u));
                                dist = min(dist, line(d,a,u));

                                if(dist < 9.){
                                        //if(O.x>.65)
                                             O = .7-vec4( smoothstep(.02, 0., dist) ) ;    
                                        return;
                                }


                           #endif
                        }
                }
        }
}
